{
  "story": "Clients and servers establish reliable connections through a three-way handshake. Each step exchanges synchronization and acknowledgment flags before data flows.",
  "aha": {
    "stateId": "step3",
    "observation": "The final ACK confirms connection establishment, allowing both peers to transmit application data."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "completedBefore": "state.completedBefore"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Handshake Step",
      "options": ["SYN Sent", "SYN-ACK Received", "Established"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "TCP Handshake",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "kind": "actor",
            "values": ["Port 5000"]
          },
          {
            "id": "wire",
            "label": "Network Channel",
            "kind": "medium",
            "values": ["Packet Transit"]
          },
          {
            "id": "server",
            "label": "Server",
            "kind": "actor",
            "values": ["Port 80"]
          }
        ],
        "states": [
          {
            "id": "step1",
            "label": "SYN",
            "short": "SYN",
            "sentence": "Client sends a SYN segment to initiate connection synchronization.",
            "why": "Establishes initial sequence number.",
            "active": ["client", "wire"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "r1",
                "label": "Client State",
                "value": "SYN_SENT"
              },
              {
                "id": "r2",
                "label": "Server State",
                "value": "LISTEN"
              }
            ]
          },
          {
            "id": "step2",
            "label": "SYN-ACK",
            "short": "SYN-ACK",
            "sentence": "Server replies with a SYN-ACK segment acknowledging the request.",
            "why": "Acknowledge client sequence and send server sequence.",
            "active": ["wire", "server"],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "r1",
                "label": "Client State",
                "value": "SYN_SENT"
              },
              {
                "id": "r2",
                "label": "Server State",
                "value": "SYN_RCVD"
              }
            ]
          },
          {
            "id": "step3",
            "label": "ACK",
            "short": "ACK",
            "sentence": "Client sends a final ACK segment confirming the server's sequence.",
            "why": "Connection is fully established.",
            "active": ["client", "wire", "server"],
            "calloutRegion": "wire",
            "readouts": [
              {
                "id": "r1",
                "label": "Client State",
                "value": "ESTABLISHED"
              },
              {
                "id": "r2",
                "label": "Server State",
                "value": "ESTABLISHED"
              }
            ]
          }
        ]
      }
    ]
  }
}
